test:
ledger = BankLedger()
ledger.open_account("a", 1)
ledger.deposit("a", 2)
rows = ledger.statement("a")
rows[0]["memo"] = "tampered"
assert ledger.statement("a")[0]["memo"] == ""
for call in (
    lambda: ledger.open_account("a"),
    lambda: ledger.open_account("", 0),
    lambda: ledger.deposit("a", 0),
    lambda: ledger.deposit("a", 1, None),
):
    try:
        call()
    except (ValueError, AssertionError):
        pass
    else:
        raise AssertionError("expected input validation error")
try:
    ledger.balance("missing")
except (KeyError, AssertionError):
    pass
else:
    raise AssertionError("expected lookup validation error")
